        "Schwimmen sa používa, keď človek pláva vo vode plaveckým pohybom.",
        "Pokiaľ ide o relax vo vode alebo plávanie, často sa používa baden.",
        "Na úrovni A1 je dôležité rozlišovať: schwimmen = plávať, baden = kúpať sa."
