        "V lotyštine sa často prekladá ako ja alebo ja.",
        "V niektorých nemeckých slovesách je sich povinnou súčasťou, napríklad sich waschen.",
        "Dôležité upozornenie na úrovni A1: ich wasche mich, er wäscht sich."
